# «Арена»: промпты ролей (совет 17). Все роли — Opus 5.5; головы не видят репозиторий и правду экспериментатора.
import json

SEMANTICS = """Язык правил — подмножество Python. Правила — функция def f(p): ... return <целое>, где p — словарь с целыми числами и списками целых.
Разрешено: целые произвольной длины, + - * // % ** (показатель ≤ 4096; для больших — pow(a, b, m)), сравнения, and/or/not, if/elif/else, for по range/спискам, while, break/continue,
списки, словари, множества, кортежи, срезы, генераторы списков, вспомогательные функции (рекурсия — глубина ≤ 200), встроенные range len min max abs sum list dict sorted reversed enumerate zip int bool set tuple any all pow divmod,
методы append pop insert extend index count get keys values items add remove discard copy sort reverse setdefault.
Запрещено: float и деление '/', import, ввод-вывод, lambda, классы, try, глобальные переменные, вложенные функции (вспомогательные функции — только на верхнем уровне), sorted/sort с key, str.
Деление только // (округление вниз, как в Python: -7 // 2 = -4), % — как в Python (знак делителя). Присваивания выполняются последовательно, a, b = b, a + b — как в Python.
Лимит: 10 000 000 шагов интерпретатора (каждый оператор и каждая итерация цикла — шаг; ≈ 1 млн итераций простого цикла ≈ 2 млн шагов) и 10 секунд."""

GAME = """Игра «Арена». Нападающие придумывают задачи, на которых защитник ошибётся. Защитники — такие же модели, как ты, у них есть Python и numpy/sympy, лимит — несколько запусков по 10 секунд.
Нападающий сдаёт задачу в двух видах: (1) проза — условие для защитника на русском; (2) правила — программа f(p) на ограниченном языке; её исполняет интерпретатор экспериментатора, и её ответ считается ПРАВДОЙ.
Плюс боевой вход p (словарь), 2–3 малых примера входа (их ответы посчитает интерпретатор и покажет защитнику вместе с прозой) и ставка — какую ошибку ты ждёшь от защитника.
Приёмка: правила исполняются интерпретатором и CPython (должны совпасть и уложиться в лимит); затем три независимых проверяющих читают прозу, примеры и твои правила и ищут ДРУГОЕ разумное прочтение прозы, которое даёт те же ответы на малых примерах, но другой ответ на боевом входе.
Если хоть один найдёт такое прочтение (это проверяет код), задача снимается как двусмысленная: тебе −2.
Очки: +1, если задача принята и защитник-одиночка ошибся в понимании условия или в счёте; 0, если он ответил верно; нехватка ресурса или неверный формат у защитника тебе очков не дают.
Значит, выигрывает задача, у которой проза честная и однозначная (внимательный читатель переводит её верно), но в которой легко ошибиться: ловушка чтения, знакомый образ с подменой, граничный случай, порядок событий, неожиданное следствие правил.
Задачи должны быть разными по типу. Ответ — одно целое число."""

def attacker(k, rnd, history):
    h = 'Это первый раунд — прошлых задач нет.' if not history else 'Твои прошлые задачи и исходы (у защитника-одиночки):\n' + '\n'.join(
        f"- раунд {x['round']}, «{x['title']}»: {x['outcome']}" for x in history)
    return (f"Ты — нападающий №{k} в игре. Раунд {rnd}.\n\n{GAME}\n\n{SEMANTICS}\n\n{h}\n\n"
            f"Работай только в каталоге /tmp/arena/att{k}_r{rnd} (создай его). Не открывай другие файлы и каталоги (ни репозиторий, ни /root): это нарушение игры. "
            f"Проверь каждую свою задачу: правила запускаются в Python, f(p) на боевом входе и на примерах возвращает целое быстро (помни про лимит шагов интерпретатора), а проза однозначно описывает ровно то, что считают правила, и содержит боевой вход.\n\n"
            f"Сдай ровно 5 задач. Для каждой: title — короткое название; prose — условие для защитника (с боевыми данными; ключи словаря p упомяни явно, например «p = {{'n': ..., 'xs': [...]}}»); "
            f"rules — текст программы с def f(p); battle — боевой вход p (JSON-объект); examples — список из 2–3 малых входов p (JSON-объекты); bet — какую ошибку ты ждёшь и почему.")

def task_view(t):
    ex = '\n'.join(f"  p = {json.dumps(e['p'], ensure_ascii=False)} → ответ {e['ans']}" for e in t['examples'])
    return (f"{t['prose']}\n\nБоевой вход: p = {json.dumps(t['battle'], ensure_ascii=False)}\n"
            f"Малые примеры (ответы посчитаны по правилам задачи):\n{ex}")

def translator(t, j):
    return (f"Ты — переводчик-проверяющий в игре, где нужно честно формализовать условие задачи. Прочитай условие и запиши его как программу def f(p) на ограниченном языке.\n\n{SEMANTICS}\n\n"
            f"Работай в каталоге /tmp/arena/tr_{t['tid']}_{j} (создай его); другие файлы и каталоги не открывай. Можешь запускать Python, чтобы проверить свою программу на малых примерах. "
            f"Твоя цель — не решить задачу быстро, а перевести условие буквально и точно; если какое-то место допускает разные прочтения, выбери то, которое точнее следует тексту, и назови это место в поле doubts.\n\n"
            f"Условие:\n{task_view(t)}\n\nВерни: rules — текст программы def f(p) на ограниченном языке; doubts — места условия, которые можно прочесть по-разному (пустая строка, если таких нет).")

def alt_reader(t, j):
    return (f"Ты — проверяющий однозначность условия в игре. Нападающий сдал условие задачи и свои правила (программу). Твоя задача — найти ДРУГОЕ разумное прочтение условия: "
            f"программу, которая тоже честно следует тексту и даёт те же ответы на всех малых примерах, но на боевом входе даёт другой ответ. Если такого прочтения нет, так и скажи.\n\n{SEMANTICS}\n\n"
            f"Работай в каталоге /tmp/arena/alt_{t['tid']}_{j} (создай его); другие файлы не открывай. Можешь запускать Python.\n\nУсловие:\n{task_view(t)}\n\nПравила нападающего:\n{t['rules']}\n\n"
            f"Верни: found — true, если нашёл другое разумное прочтение; rules — его программа def f(p) (пустая строка, если не нашёл); reading — какое место условия прочитано иначе.")

DEF_TAIL = ("Работай только в своём каталоге {dir} (создай его). Не открывай другие файлы и каталоги (ни репозиторий, ни /root): там ответа нет, и это нарушение игры. "
            "Можно Python, numpy, sympy. Бюджет: не больше {K} запусков программ, каждый не дольше 10 секунд. Будь внимателен: задачу придумали, чтобы ты ошибся.\n\n")
def solo(t, K, history=None, tag='solo'):
    h = ''
    if history:
        h = 'Твои задачи из прошлых раундов (что ты ответил и что было верно):\n' + '\n'.join(
            f"- «{x['title']}»: ты ответил {x['given']}, верно {x['truth']}; {x['kind']}" for x in history) + '\n\n'
    return (f"Ты — защитник в игре «Арена»: реши задачу и дай точный ответ — целое число.\n" + DEF_TAIL.format(dir=f"/tmp/arena/{tag}_{t['tid']}", K=K) + h +
            f"Условие:\n{task_view(t)}\n\nВерни: answer — ответ на боевой вход (только цифры, со знаком минус, если нужно); "
            f"program — полный текст программы на Python с функцией def f(p), которая считает ответ по входу p (её запустят на боевом входе и на примерах); runs — сколько запусков ты сделал.")
def checker(t, K, sol):
    return (f"Ты — сверщик в команде защитников игры «Арена». Решатель из твоей команды уже решил задачу. Проверь его работу: верно ли он понял условие, нет ли ловушки, верно ли посчитано. "
            f"Если нашёл ошибку — исправь. Итоговый ответ команды даёшь ты.\n" + DEF_TAIL.format(dir=f"/tmp/arena/chk_{t['tid']}", K=K) +
            f"Условие:\n{task_view(t)}\n\nОтвет решателя: {sol.get('answer')}\nПрограмма решателя:\n{sol.get('program')}\n\n"
            f"Верни: answer — итоговый ответ команды (только цифры); program — программа def f(p), которая даёт итоговый ответ; runs — сколько запусков ты сделал; changed — изменил ли ты ответ решателя.")
